// Helper function to count occurrences of an element in the list
function CountOccurrences(numbers: array<int>, x: int) : int
    requires numbers != null
    ensures 0 <= CountOccurrences(numbers, x)
{
    var count := 0;
    var i := 0;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant count == CountOccurrences(numbers[0..i], x)
    {
        if numbers[i] == x {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to count duplicates
function CountDuplicates(numbers: array<int>) : int
    requires numbers != null
    ensures 0 <= CountDuplicates(numbers)
{
    var count := 0;
    var i := 0;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant count == CountDuplicates(numbers[0..i])
    {
        if CountOccurrences(numbers, numbers[i]) > 1 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
